{
  "table": {
    "name": "Examination",
    "purpose": "Clinical examination/visit record for a rheumatology/autoimmune-disease cohort (mostly SLE, Sjögren's, RA, MCTD patients), capturing visit date, lab/serology findings, ANA results, diagnosis, and disease complications."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "patient_id",
      "description": "Likely a patient identifier (7-digit hospital-style ID, near-unique across rows). No joins detected to Patient/Laboratory, so the link is not confirmed; could alternatively be a visit/exam record number.",
      "status": "tentative"
    },
    "col_002": {
      "role": "date",
      "name": "examination_date",
      "description": "Date of the examination/visit, ranging 1989-04-18 to 1998-04-17.",
      "status": "resolved"
    },
    "col_003": {
      "role": "numeric",
      "name": "crp",
      "description": "A lab value with median 0.8 and values like 17.3, 59.6 — plausibly C-reactive protein (mg/dL), where 0 is normal. Max 2150.3 is an outlier or different unit. Not confirmed; could be another inflammatory marker.",
      "status": "tentative"
    },
    "col_004": {
      "role": "numeric",
      "name": "",
      "description": "A lab value, median 2.1, mostly small but with extreme outliers up to 187122. Could be an ESR-like or titer-like measure, but the distribution does not clearly match a known unit; meaning unresolved.",
      "status": "unresolved"
    },
    "col_005": {
      "role": "numeric",
      "name": "ana_titer",
      "description": "Values are exclusively powers of two (0, 4, 16, 64, 256, 1024, 4096), the classic pattern of an immunofluorescence antibody titer (e.g., ANA titer expressed as reciprocal dilution); 0 = negative/not done.",
      "status": "tentative"
    },
    "col_006": {
      "role": "code",
      "name": "ana_pattern",
      "description": "Comma-separated codes S, P, D (also lowercase 'p', and 'P.D' typo) — plausibly ANA staining patterns: S = speckled, P = peripheral/rim, D = diffuse/homogeneous. Multiple patterns can co-occur. Not confirmed against a lookup.",
      "status": "tentative"
    },
    "col_007": {
      "role": "numeric",
      "name": "",
      "description": "Small non-negative integer, mostly 0, max 48547 (outlier). Could be a count (e.g., joint count, symptom count) but evidence is insufficient.",
      "status": "unresolved"
    },
    "col_008": {
      "role": "code",
      "name": "diagnosis",
      "description": "Diagnosis at examination: SLE, SjS (Sjögren's), RA, MCTD, DM, plus qualifiers like 'WHOIV' (WHO class IV lupus nephritis), 'ITP', 'LA(-)', 'susp' (suspected).",
      "status": "resolved"
    },
    "col_009": {
      "role": "code",
      "name": "",
      "description": "A +/- serological test result (mostly '-'). Which antibody/test it represents is unknown; could be anti-dsDNA, anti-Sm, LE cell prep, etc.",
      "status": "unresolved"
    },
    "col_010": {
      "role": "code",
      "name": "",
      "description": "A +/- serological test result (mostly '-'); specific test unknown.",
      "status": "unresolved"
    },
    "col_011": {
      "role": "code",
      "name": "",
      "description": "A +/- serological test result (mostly '-'); specific test unknown.",
      "status": "unresolved"
    },
    "col_012": {
      "role": "code",
      "name": "complications",
      "description": "Disease complications/comorbid events: CNS lupus, brain infarction, AMI, PH (pulmonary hypertension), thrombocytopenia, DVT, thrombophlebitis, abortion, etc. Mostly null (no complication).",
      "status": "resolved"
    },
    "col_013": {
      "role": "numeric",
      "name": "complication_count",
      "description": "Small count 0-3, mostly 0 — plausibly the number of complications recorded for the visit (matches col_012 being mostly null). Could alternatively be a severity grade.",
      "status": "tentative"
    }
  }
}
